Translate("ruRU", "humans", {
	title = "Люди",
	sections = {
		{
			title = "Обзор",
			text = [=[Люди — самый многочисленный из молодых народов {link:eastern-kingdoms}Восточных королевств{/link}. Рядом с эльфами и {link:dwarves}дворф{/link}ами их век короток, но они неугомонны, упрямы и быстро учатся. Из их родов поднялись великие королевства севера и юга, а из их рядов вышли паладины {link:holy-light}Света{/link} и маги {link:dalaran}Даларана{/link}. В войнах с {link:orcs}орк{/link}ами и нежитью они пострадали больше любого другого народа, и они до сих пор не сломлены.]=],
		},
		{
			title = "Истоки",
			text = [=[В древние времена люди жили на севере разрозненными племенами, и каждое не доверяло остальным. Одно лишь племя {link:arathi-highlands}Арати{/link} понимало, что империя {link:trolls}троллей{/link} Амани уничтожит их поодиночке. Их военный вождь {link:thoradin}Торадин{/link} связал племена воедино силой и убеждением и на их союзе основал державу {link:arathor}Аратор{/link} и ее город-крепость {link:stromgarde-keep}Стром{/link}. Когда Амани пошли на {link:high-elves}высших эльфов{/link} королевства {link:quel-thalas}Кель'Талас{/link}, Аратор откликнулся на зов эльфов. Эльфы обучили сотню людей {link:arcane-magic}тайной магии{/link}, и вместе два народа сокрушили Амани в {link:troll-wars}Войнах с троллями{/link}.

В долгом мире, который настал потом, единство Аратора угасло. Его народ расселился по земле и основал новые державы: {link:lordaeron}Лордерон{/link} на севере, {link:gilneas}Гилнеас{/link} и {link:kul-tiras}Кул Тирас{/link} на западных берегах, {link:alterac-mountains}Альтерак{/link} и Стромгард в горах, {link:city-of-dalaran}город магов{/link} {link:dalaran}Даларан{/link}, а далеко на юге — королевство {link:azeroth}Азерот{/link}, которое теперь зовут {link:kingdom-of-stormwind}королевством Штормград{/link}.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Люди — народ королей и земледельцев. Их знать хранит старые дома и еще более старые распри, а простолюдины пашут землю и мало думают о тех и других. Церковь {link:holy-light}Свет{/link}а связывает многих из них, и ее священники есть в каждой деревне. Люди ценят клятвы, отвагу и долг, хотя и не всегда им верны. Величайший их дар — умение отстраивать заново. Что бы ни сгорело, они возводят это опять.]=],
		},
		{
			title = "Наши дни",
			text = [=[Королевства людей — лишь тени их былой славы. {link:scourge}Плеть{/link} владеет руинами {link:lordaeron}Лордерон{/link}а, а {link:scarlet-crusade}Алый орден{/link} ведет на севере собственную беспощадную войну. {link:gilneas}Гилнеас{/link} затворился за своей великой стеной. {link:alterac-mountains}Альтерак{/link} разрушен, а {link:stromgarde-keep}Стромгард{/link} цепляется за то, что осталось от Нагорья {link:arathi-highlands}Арати{/link}. На юге стоит отстроенный {link:stormwind-city}Штормград{/link}, но король {link:varian-wrynn}Вариан Ринн{/link} исчез, и его именем правит верховный лорд {link:bolvar-fordragon}Болвар Фордрагон{/link}. За морем леди {link:jaina-proudmoore}Джайна Праудмур{/link} держит островную крепость {link:theramore-isle}Терамор{/link}, где люди хранят непрочный мир с {link:horde}Ордой{/link}. Человечество остается сердцем {link:alliance}Альянса{/link}, и это сердце кровоточит.]=],
		},
	},
})

Translate("ruRU", "dwarves", {
	title = "Дворфы",
	aliases = { "дворф" },
	sections = {
		{
			title = "Обзор",
			text = [=[Дворфы — коренастый и выносливый народ гор Каз Модана. Они рудокопы, кузнецы, пивовары и воины и одни из лучших мастеров в мире. Их великий город {link:ironforge}Стальгорн{/link} высечен в сердце горы. Они сражаются рядом с людьми со времен {link:second-war}Второй войны{/link} и остаются одним из столпов {link:alliance}Альянса{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Веками дворфы жили под горами, и их собственные предания гласили, что они созданы из камня. В залах {link:uldaman}Ульдамана{/link} ученые {link:explorers-league}Лиги исследователей{/link} нашли записи титанов, которые, похоже, это подтверждают: в них говорится о земельниках, существах из живого камня, которых титаны сотворили, чтобы придавать облик глубинам мира. Многие дворфы теперь верят, что их народ происходит от них.

Дворфы долго были едины под властью одного верховного короля в {link:ironforge}Стальгорн{/link}е. Когда этот король умер, три великих клана пошли войной за его трон. В этой Войне Трех Молотов клан Бронзобородов удержал Стальгорн. Клан Неистового Молота вытеснили на север, и со временем он обрел дом во {link:the-hinterlands}Внутренних землях{/link}. Клан Черного Железа отбросили на юг. Там его король-чародей {link:ruins-of-thaurissan}Тауриссан{/link} искал силу, чтобы отомстить за поражение, и призвал Повелителя Огня {red:ragnaros}Рагнароса{/red}. Пламя этого призыва раскололо землю и приковало дворфов Черного Железа к службе Повелителю Огня.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Дворфы горды, верны и не скоры на прощение. Они любят добрый эль, громкую песню и ладно сработанный топор. Дела они уважают больше слов и славятся долгой памятью. Их оружейники известны по всем Восточным королевствам, а их ружья и пушки отстояли немало стен. Дворфы Неистового Молота нравом диче своей родни и летят в бой на грифонах, а Бронзобороды предпочитают горн и ружье.]=],
		},
		{
			title = "Наши дни",
			text = [=[В {link:ironforge}Стальгорн{/link}е правит король {link:magni-bronzebeard}Магни Бронзобород{/link}. Его брат {link:brann-bronzebeard}Бранн Бронзобород{/link} возглавляет Лигу исследователей, чьи землекопы роются в руинах по всему миру в поисках истинного прошлого дворфов. Стальгорн открыл ворота {link:gnomes}гномам{/link}, у которых {link:troggs}трогги{/link} отняли город, и теперь {link:tinker-town}Город Механиков{/link} звенит от гномьей работы. {link:dark-iron-dwarves}Дворфы Черного Железа{/link} остаются злейшими врагами своих сородичей и трудятся в глубинах Черной горы на службе у Повелителя Огня. Дворфы Неистового Молота живут своим умом во {link:the-hinterlands}Внутренних землях{/link}: они союзники Стальгорна, но никогда не были его подданными.]=],
		},
	},
})

Translate("ruRU", "gnomes", {
	title = "Гномы",
	aliases = { "гном" },
	sections = {
		{
			title = "Обзор",
			text = [=[Гномы — маленький, смышленый и бесконечно любопытный народ. Они величайшие механики и инженеры в мире, и во всем, что им встречается, видят задачу, которую надо решить. Поколениями они жили в дивном городе {link:gnomeregan}Гномреган{/link} в горах {link:dun-morogh}Дун Морог{/link}а. Теперь этот город для них потерян, и они живут гостями {link:dwarves}дворфов{/link} в {link:ironforge}Стальгорне{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Гномы издавна были соседями и друзьями {link:dwarves}дворф{/link}ов Каз Модана. Об их ранних днях летописи {link:azeroth}Азерот{/link}а говорят мало. Достоверно то, что {link:gnomeregan}Гномреган{/link} они построили своими руками и наполнили его чудесами: {link:ogres}огр{/link}омными машинами, заводными слугами и устройствами, какие не вообразил бы ни один другой народ. Во {link:second-war}Второй войне{/link} они вступили в {link:alliance}Альянс{/link} вместе с дворфами. Солдат они послали мало, ибо народ их невелик, но дали Альянсу летающие машины, подводные лодки и оружие собственной выдумки.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Гномы сообразительны, проворны и бодры духом даже в самые темные часы. Они также легко отвлекаются, и их изобретения не всегда делают то, что задумали создатели. Смекалку они ставят выше силы, а своих мастеров-инженеров окружают высочайшим почетом. Их предводитель носит звание главного механика. Многие гномы изучают и {link:arcane-magic}тайную магию{/link}, а иные обращаются к более темным искусствам, которые, по мнению других, лучше не трогать.]=],
		},
		{
			title = "Наши дни",
			text = [=[После {link:third-war}Третьей войны{/link} {link:troggs}трогги{/link} поднялись из-под земли и хлынули в {link:gnomeregan}Гномреган{/link}. Город нельзя было удержать. Главный механик {link:gelbin-mekkatorque}Гелбин Меггакрут{/link} сделал отчаянный выбор и пустил в ход ядовитое оружие, чтобы выгнать захватчиков. Оно убило многих троггов, но убило и великое множество гномов, а город оставило отравленным. Уцелевшие бежали в {link:ironforge}Стальгорн{/link}. Теперь шепчут, что падение не было случайностью: говорят, что народ предал собственный советник главного механика, {link:mekgineer-thermaplugg}Сикко Термоштепсель{/link}, и что теперь он правит разрушенным городом как его безумный хозяин. Гномы мечтают о дне, когда вернут себе дом. А до тех пор они мастерят в Стальгорне и служат {link:alliance}Альянс{/link}у с тем же рвением, какое выказывали всегда.]=],
		},
	},
})

Translate("ruRU", "night-elves", {
	title = "Ночные эльфы",
	aliases = { "калдореи", "ночной эльф" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ночные эльфы, которые зовут себя калдореи, или «дети звезд», — старейший просвещенный народ {link:kalimdor}Калимдора{/link}. Они высоки, кожа у них лиловая, а век долог, и десять тысяч лет они стерегут леса севера. Их жрицы служат богине луны Элуне, а их друиды берегут дикую природу так, как учил полубог {link:cenarius}Кенарий{/link}. После {link:third-war}Третьей войны{/link} они впервые в своей истории вступили в {link:alliance}Альянс{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Первые ночные эльфы были племенем, которое в древности поселилось на берегах {link:well-of-eternity}Источника Вечности{/link}. Сила Источника изменила их и дала им долгую жизнь. На его берегах они воздвигли великую империю, которой правили {link:queen-azshara}королева Азшара{/link} и ее каста чародеев-высокорожденных. Высокорожденные опьянели от силы Источника, и наконец их магия привлекла взор {link:burning-legion}Пылающего Легиона{/link}. {link:azshara}Азшара{/link} открыла путь демонам, и началась {link:war-of-the-ancients}Война древних{/link}.

Друид {link:malfurion-stormrage}Малфурион Ярость Бури{/link}, жрица {link:tyrande-whisperwind}Тиранда Шелест Ветра{/link} и их союзники отбросили Легион. В конце концов Источник был уничтожен, и {link:great-sundering}Великий Раскол{/link} разбил древний материк. Уцелевшие ночные эльфы отвернулись от тайной магии. На горе Хиджал они растили новое древо жизни, {link:nordrassil}Нордрассил{/link}, которое даровало им бессмертие. Высокорожденных, которые отказались оставить свою магию, отправили в изгнание за море.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Ночные эльфы — терпеливый и бдительный народ. Их женщины издавна служили Часовыми, воительницами, которые стерегут леса, а мужчины становились друидами и долгие годы спали в {link:emerald-dream}Изумрудном Сне{/link}. Они любят дикие места мира и ненавидят тех, кто их разоряет. Тайной магии они не доверяют, ибо она едва не погубила их мир.]=],
		},
		{
			title = "Наши дни",
			text = [=[В Третью войну Легион вернулся. В {link:battle-of-mount-hyjal}Битве у горы Хиджал{/link} ночные эльфы, люди и {link:orcs}орк{/link}и встали вместе против демона {link:archimonde}Архимонда{/link}, и вся сила древа {link:nordrassil}Нордрассил{/link} ушла на то, чтобы уничтожить его. С нею ночные эльфы потеряли бессмертие. Затем верховный друид {link:fandral-staghelm}Фэндрал Олений Шлем{/link} и его друиды вырастили у северного побережья новое Мировое Древо, {link:teldrassil}Тельдрассил{/link}, и в его ветвях вырос город {link:darnassus}Дарнасс{/link}. {link:tyrande-whisperwind}Тиранда{/link} правит там как верховная жрица, а {link:malfurion-stormrage}Малфурион{/link} странствует в Изумрудном Сне и не вернулся. Ныне калдореи противостоят оркам, которые рубят леса {link:ashenvale}Ясеневого леса{/link}, и порче, которая расползается по {link:felwood}Оскверненному лесу{/link}.]=],
		},
	},
})

Translate("ruRU", "orcs", {
	title = "Орки",
	aliases = { "орк" },
	sections = {
		{
			title = "Обзор",
			text = [=[Орки — гордый народ воинов из мира Дренор. Они пришли в {link:azeroth}Азерот{/link} завоевателями через {link:dark-portal}Темный портал{/link} и принесли королевствам людей огонь и разорение. Их разбили, заточили и сломили, но они поднялись вновь. Под началом своего вождя {link:thrall}Тралла{/link} они пересекли море, пришли в {link:kalimdor}Калимдор{/link} и построили новую родину в {link:durotar}Дуротаре{/link}. Они — сердце {link:horde}Орды{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[В мире Дренор орки жили множеством кланов. Они были охотниками и воинами, а вели их шаманы, которые говорили с духами {link:elements}стихий{/link}. Повелитель демонов {link:kil-jaeden}Кил'джеден{/link} задумал сделать из них оружие {link:burning-legion}Пылающего Легиона{/link}. Он обманул старейшего шамана {link:ner-zhul}Нер'зула{/link}, а после него — ученика этого шамана, {link:gul-dan}Гул'дана{/link}. Гул'дан научил кланы искусству чернокнижников, и стихии отвернулись от орков. {link:nak}Нак{/link}онец вожди выпили кровь демона {link:mannoroth}Маннорот{/link}а, и жажда крови овладела всем народом.

Через {link:dark-portal}Темный портал{/link} {link:horde}Орда{/link} обрушилась на королевство {link:azeroth}Азерот{/link}. Она выиграла {link:first-war}Первую войну{/link} и сожгла {link:stormwind-city}Штормград{/link}. Под началом вождя {link:orgrim-doomhammer}Оргрима Молота Рока{/link} она едва не выиграла и {link:second-war}Вторую войну{/link}, но ее предали изнутри, и она была разбита. Уцелевших орков согнали в лагеря для пленных, где на них сошло странное оцепенение.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Орки чтят силу, отвагу и верность клану. Они уважают шамана, который говорит за духов, и воина, который стоит в бою твердо. Их имена горды, и такова же их память: каждый клан хранит свои предания и свои обиды. С тех пор как пало проклятие демона, многие орки вернулись к старым путям шаманов и ищут равновесия со стихиями.]=],
		},
		{
			title = "Наши дни",
			text = [=[Молодой орк {link:thrall}Тралл{/link}, выросший рабом в человеческой крепости, бежал от хозяев и освободил свой народ из лагерей. По зову пророка он повел орков на запад, в {link:kalimdor}Калимдор{/link}. Там, в {link:third-war}Третью войну{/link}, {link:grom-hellscream}Гром Адский Крик{/link} убил демона {link:mannoroth}Маннорот{/link}а и освободил орков от демонической крови. Тралл назвал свою новую землю {link:durotar}Дуротар{/link}ом в честь своего отца Дуротана, а столицу — {link:orgrimmar}Оргриммаром{/link} в честь вождя Молота Рока. Ныне орки хранят непрочный мир с {link:theramore-isle}Терамором{/link}. Но не все орки отвернулись от старой тьмы. Культ {link:burning-blade}Пылающего Клинка{/link} шепчет в пещерах Дуротара, а в Восточных королевствах {link:blackrock-clan}клан Черной горы{/link} все еще служит черным драконам в Черной горе.]=],
		},
	},
})

Translate("ruRU", "trolls", {
	title = "Тролли",
	sections = {
		{
			title = "Обзор",
			text = [=[Тролли — один из самых древних народов {link:azeroth}Азерота{/link}. Они высоки, клыкасты и свирепы, а их тела заживляют раны, которые убили бы любое другое существо. Задолго до того, как ночные эльфы воздвигли свою империю, тролли правили собственными великими державами. Эти империи пали, а уцелевшие племена озлоблены, разобщены и опасны. Одно из них, {link:darkspear-trolls}племя Черного Копья{/link}, теперь стоит на стороне {link:horde}Орды{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Старейшим королевством троллей было королевство племени Зандалар, которое обитало далеко на юге. От него пошли две великие империи древности: Амани в северных лесах и Гурубаши в южных джунглях. Они поклонялись могучим духам, которых зовут лоа, воевали с первыми ночными эльфами и проиграли. {link:great-sundering}Великий Раскол{/link} разорвал их земли.

Тролли Амани так и не простили высших эльфов, которые поселились в их лесах. В {link:troll-wars}Войнах с троллями{/link} они едва не уничтожили {link:quel-thalas}Кель'Талас{/link}, пока люди {link:arathor}Аратора{/link} не пришли на помощь эльфам и не сокрушили их. На юге Гурубаши п{link:ogres}огр{/link}узились в междоусобную войну, когда жрецы Атал'ай призвали кровавого бога {link:hakkar}Хаккара{/link}. Племена низвергли бога и загнали Атал'ай в болота, где те построили храм {link:temple-of-atal-hakkar}Атал'Хаккар{/link}а. Их империя так и не оправилась.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Тролли — охотники и налетчики. Их жрецы занимаются вуду и говорят с лоа, а их знахари варят зелья и наводят порчу, которой боятся другие народы. Многие племена держатся жестоких обычаев, а о некоторых говорят, что они едят своих врагов. Они гордятся своим древним прошлым и таят обиду на молодые народы, которые заняли их земли. Мало кто из троллей доверяет чужакам, и еще меньше тех, кому доверяют в ответ.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:darkspear-trolls}Племя Черного Копья{/link} изгнали из родных джунглей, и оно нашло убежище в южных морях. Там {link:thrall}Тралл{/link} спас его от людей и от морской ведьмы, а предводитель племени Сен'джин отдал жизнь, чтобы его народ мог пойти за {link:orcs}орк{/link}ами. Сегодня тролли Черного Копья служат Орде, и ведет их {link:vol-jin}Вол'джин{/link}. Они заселили {link:echo-isles}Острова Эха{/link} у берегов {link:durotar}Дуротара{/link}, но знахарь {link:zalazane}Залазан{/link} захватил острова темной магией, и племя отошло на материк, в Деревню Сен'джин. В других местах племена троллей остаются врагами всем: Амани в северных лесах, {link:witherbark-trolls}Сухокожие{/link} и Порочная Ветвь во {link:the-hinterlands}Внутренних землях{/link}, племена Гурубаши в {link:stranglethorn-vale}Тернистой долине{/link}, {link:sandfury-trolls}племя Песчаной Бури{/link} в {link:tanaris}Танарисе{/link} и {link:frostmane-trolls}Мерзлогривы{/link} в {link:dun-morogh}Дун Морог{/link}е.]=],
		},
	},
})

Translate("ruRU", "tauren", {
	title = "Таурены",
	aliases = { "таурен", "шу'хало" },
	sections = {
		{
			title = "Обзор",
			text = [=[Таурены — народ великого роста и кроткой мудрости, который кочует по равнинам {link:kalimdor}Калимдора{/link}. Они {link:ogres}огр{/link}омны и похожи на быков, и в бою могут быть страшны, но предпочли бы жить в мире с землей. Превыше всего они чтят Мать-Землю. Под началом своего великого вождя {link:cairne-bloodhoof}Кэрна Кровавого Копыта{/link} они заселили луга {link:mulgore}Мулгора{/link} и вступили в {link:horde}Орду{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Таурены, которые зовут себя шу'хало, — один из старейших народов {link:kalimdor}Калимдор{/link}а. Веками они бродили по равнинам кочевниками, следуя за великими стадами и сменой времен года. Они говорят, что землю им дала Мать-Земля, а солнце и луна — ее глаза, которые они называют Ан'ше и Му'ша. Племена жили врозь, каждое со своими вождями и своими тотемами.

Этой жизни едва не положили конец {link:centaurs}кентавры{/link}. Жестокие люди-кони равнин поколениями охотились на разрозненные племена и согнали их с земель предков. {link:cairne-bloodhoof}Кэрн Кровавое Копыто{/link} взялся объединить племена против них. Когда {link:orcs}орк{/link}и пришли в Калимдор, Кэрн встретил молодого вождя {link:thrall}Тралла{/link}, и два народа узнали друг в друге родню по духу. С помощью орков таурены сломили власть кентавров над {link:mulgore}Мулгор{/link}ом и объявили его своей родиной.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Таурены живут близко к земле. Они охотятся с почтением и берут только то, что им нужно. Их шаманы говорят с духами {link:elements}стихий{/link} и предков, а некоторые таурены постигли пути друидов, обучившись у ночных эльфов {link:cenarion-circle}Круга Кенария{/link}. Они терпеливы, не скоры на гнев и честны до крайности. Их тотемы хранят родословные и деяния их племен.]=],
		},
		{
			title = "Наши дни",
			text = [=[Таурены построили свою столицу, {link:thunder-bluff}Громовой Утес{/link}, на высоких столовых горах над {link:mulgore}Мулгор{/link}ом, куда поднимаются на {link:ogres}огр{/link}омных подъемниках. {link:cairne-bloodhoof}Кэрн{/link} правит там как верховный вождь, и его уважают даже те, кто боится Орды. Не все племена разделяют его взгляды. Племя Зловещего Тотема, которое ведет старая карга {link:magatha-grimtotem}Магата{/link}, лелеет собственные замыслы, и многие в Громовом Утесе мало ему доверяют. Вокруг Мулгора у тауренов по-прежнему есть враги: {link:quilboar}свинобраз{/link}ы племени Дыбогривов, гарпии горных гряд и {link:centaurs}кентавр{/link}ы {link:the-barrens}Степей{/link}. Таурены чтят свой долг перед {link:orcs}орк{/link}ами и остаются одними из самых стойких в Орде.]=],
		},
	},
})

Translate("ruRU", "forsaken", {
	title = "Отрекшиеся",
	sections = {
		{
			title = "Обзор",
			text = [=[Отрекшиеся — нежить, которая вырвалась из-под воли Короля-лича. Некогда они были народом {link:lordaeron}Лордерона{/link}. Они умерли от чумы, восстали рабами {link:scourge}Плети{/link}, а потом, в единственный час, когда хватка их хозяина ослабла, вновь обрели собственный разум. Они идут за Королевой банши {link:sylvanas-windrunner}Сильваной Ветрокрылой{/link} и создали темное королевство под руинами своей старой столицы. По собственным причинам они вступили в {link:horde}Орду{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[В {link:third-war}Третью войну{/link} чума {link:cult-of-the-damned}Культа Проклятых{/link} прокатилась по {link:lordaeron}Лордерон{/link}у, а принц {link:arthas-menethil}Артас Менетил{/link} убил своего отца, {link:terenas-menethil}Теренаса Менетила{/link}, и отдал королевство Плети. Тысячи умерших восстали вновь на службе у Короля-лича. Какое-то время у них вовсе не было воли.

Потом сила Короля-лича дрогнула, и многие мертвецы Лордерона обнаружили, что снова могут думать сами. {link:sylvanas-windrunner}Сильвана Ветрокрылая{/link}, павшая предводительница следопытов {link:quel-thalas}Кель'Таласа{/link}, была поднята в облике банши самим ее убийцей, Артасом. Она вырвалась на свободу вместе с ними. Она обратилась против повелителей ужаса, которые хотели править разрушенным королевством, и приковала к своей службе одного из них, {link:varimathras}Вариматаса{/link}. Она назвала свой народ Отрекшимися и повела его занять руины столицы Лордерона.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Отрекшиеся помнят свою жизнь, но вернуться к ней не могут. Их друзья и родные боятся и ненавидят их, и многие из них научились ненавидеть в ответ. Они мрачны, озлоблены и расчетливы. Их ученые без стыда занимаются всяким искусством алхимии и некромантии, а их жрецы отвернулись от {link:holy-light}Света{/link} и обратились к тени. Среди живых их скорее терпят, чем им доверяют.]=],
		},
		{
			title = "Наши дни",
			text = [=[Под разбитым городом {link:lordaeron}Лордерон{/link}а Отрекшиеся возвели {link:undercity}Подгород{/link}, лабиринт залов и сточных каналов, построенный в старых королевских склепах. {link:ott}Отт{/link}уда {link:sylvanas-windrunner}Сильвана{/link} правит {link:tirisfal-glades}Тирисфальскими лесами{/link} и ведет войну на две стороны: против Плети, которая все еще держит Чумные земли, и против {link:scarlet-crusade}Алого ордена{/link}, который сжигает всякую нежить, какую найдет. Их союз с Ордой — союз по нужде. Оркам и {link:tauren}таурен{/link}ам они кажутся странными и тревожащими. Сами же Отрекшиеся мало говорят о своих истинных целях, а химики {link:royal-apothecary-society}Королевского общества аптекарей{/link} втайне трудятся над новой чумой.]=],
		},
	},
})

Translate("ruRU", "skyborne", {
	title = "Рожденные Небом",
	aliases = { "шен'дорай" },
	sections = {
		{
			title = "Обзор",
			text = [=[Рожденные Небом, которые зовут себя шен'дорай, или «сокрытый народ», — эльфы, тысячи лет жившие за пределами самого мира. Их дом — {link:zephras-isle}Зефрас{/link}, остров, который парит в {link:skywall}Небесной Выси{/link}, стихийном плане воздуха. В них течет кровь высокорожденных, и они приходятся родней {link:high-elves}высшим эльфам{/link} {link:quel-thalas}Кель'Таласа{/link}. Теперь их небесная держава рушится, и новое поколение Рожденных Небом спустилось в {link:azeroth}Азерот{/link} в поисках ответов.]=],
		},
		{
			title = "Истоки",
			text = [=[Рожденные Небом ведут свой род от высокорожденных города Эльдре'Талас в {link:feralas}Фераласе{/link}, который теперь зовут {red:dire-maul}Забытым Городом{/red}. После {link:war-of-the-ancients}Войны древних{/link} принц {red:tortheldrin}Тортелдрин{/red} стремился поддерживать город все более опасными силами. Некоторые из его подданных видели, что такая жажда силы сделала с миром, и восстали против него. Они расстроили его замыслы, но их мятеж подавили, и они бежали за море, а флот принца шел за ними по пятам.

Далеко на западе они наткнулись на землю, которой правили древние духи {link:elements}стихий{/link}. Там они заключили договор с духами ветра. Духи вырвали большую часть той земли в небо, унесли ее из мира и закрепили в Небесной Выси. Скрытые от преследователей, изгнанники построили среди облаков маленькую и светлую державу.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Долгие века в Небесной Выси изменили народ шен'дорай. Они стали легче и быстрее своих предков, а магия воздуха отметила их волосы, глаза и кожу. Они жили рядом с духами ветра как ученики и друзья. Некоторые из них получили от духов дар небесного зрения, способность видеть через весь стихийный план. Духи редко говорили о хозяине Небесной Выси, Повелителе Ветра {link:al-akir}Ал'Акире{/link}, и среди Рожденных Небом его имя стало предметом страха и молчания.]=],
		},
		{
			title = "Наши дни",
			text = [=[Без всякого предупреждения {link:vanishing-of-the-wind-spirits}духи ветра{/link} исчезли. Древние пилоны, которые скрепляют {link:zephras-isle}остров Зефрас{/link}, начали отказывать, части острова обратились в руины, а его общины отрезаны друг от друга. Рожденные Небом расходятся в том, что делать.

• {b}{link:windshapers}Ваятели Ветра{/link}.{/b} Потомки первых шен'дорай, получивших небесное зрение, они духовные наставники острова. Они хотят узнать, что стало с духами ветра, и вернуть их. Они вступили в {link:horde}Орду{/link}.
• {b}{link:high-order}Высший орден{/link}.{/b} Потомки магистров-высокорожденных, бежавших из Эльдре'Таласа, они считают, что Рожденные Небом слишком доверяли своим покровителям. Они ищут тайные знания, утраченные их предками, чтобы их народ мог стоять на собственных ногах. Они вступили в {link:alliance}Альянс{/link}.
• {b}{link:al-aketh}Ал'Акет{/link}.{/b} Культ, который отвернулся от прочих шен'дорай, чтобы служить Повелителю Ветра {link:al-akir}Ал'Акир{/link}у. Осмелев без духов, они сеют страх и захватили большую часть острова.]=],
		},
	},
})

Translate("ruRU", "high-elves", {
	title = "Высшие эльфы",
	aliases = { "кель'дорай", "высший эльф" },
	sections = {
		{
			title = "Обзор",
			text = [=[Высшие эльфы, или кель'дорай, — дети изгнанников-высокорожденных, которые пересекли море после {link:great-sundering}Великого Раскола{/link}. В лесах северного {link:lordaeron}Лордерон{/link}а они построили королевство {link:quel-thalas}Кель'Талас{/link} и его сияющую столицу, Луносвет. Тысячи лет они были мастерами {link:arcane-magic}тайной магии{/link} в {link:eastern-kingdoms}Восточных королевствах{/link}. В {link:third-war}Третью войну{/link} их королевство было почти уничтожено.]=],
		},
		{
			title = "Истоки",
			text = [=[После {link:great-sundering}Раскол{/link}а ночные эльфы запретили пользоваться тайной магией. Высокорожденных, которые не пожелали подчиниться и которых вел {red:dath-remar-sunstrider}Дат'Ремар Солнечный Скиталец{/red}, изгнали. Они отплыли на восток и после долгих скитаний пришли в северные леса, где сражались за новый дом с {link:trolls}троллями{/link} Амани. Там они создали Солнечный Колодец, источник тайной силы, который питал их народ. Когда Амани поднялись против них, они заключили союз с {link:humans}людьми{/link} {link:arathor}Аратора{/link} и обучили их магии, и вместе они выиграли {link:troll-wars}Войны с троллями{/link}.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Высшие эльфы изящны, горды и учены. Они любят красоту и магию, и многие из них смотрят на молодые народы свысока. Их следопыты — лучшие лучники севера. Их связь с Солнечным Колодцем была так глубока, что они стали зависеть от его силы.]=],
		},
		{
			title = "Наши дни",
			text = [=[В Третью войну {link:arthas-menethil}Артас Менетил{/link} привел {link:scourge}Плеть{/link} в {link:quel-thalas}Кель'Талас{/link}. Он убил короля Анастериана Солнечного Скитальца и с помощью Солнечного Колодца поднял лича {link:kel-thuzad}Кел'Тузада{/link}. Предводительница следопытов {link:sylvanas-windrunner}Сильвана Ветрокрылая{/link} пала, защищая родину. Немногие уцелевшие остаются рассеянными: одни все еще держат то, что осталось от Кель'Таласа, другие служат {link:alliance}Альянсу{/link} и {link:kirin-tor}Кирин-Тору{/link}, а небольшой отряд хранит охотничью сторожку {link:quel-danil-lodge}Кель'Данил{/link} во {link:the-hinterlands}Внутренних землях{/link}. Принц Кель'тас, наследник рода Солнечных Скитальцев, собрал многих уцелевших и дал им новое имя — син'дорай, эльфы крови, в память о павших. Что стало с ним потом, не скажет ни одна летопись этих земель.]=],
		},
	},
})

Translate("ruRU", "kobolds", {
	title = "Кобольды",
	aliases = { "кобольд" },
	sections = {
		{
			title = "Обзор",
			text = [=[Кобольды — мелкие существа, похожие на крыс, которые живут в шахтах и пещерах по всему {link:azeroth}Азероту{/link}. Они трусливы, жадны и не слишком умны, зато их великое множество. Стоит оставить старую шахту без охраны, как в нее вселяются кобольды. Каждый носит на голове свечу, чтобы освещать ходы, и каждый скорее умрет, чем отдаст ее.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не говорит, откуда впервые явились кобольды. Некоторые землекопы {link:explorers-league}Лиги исследователей{/link} считают, что они произошли от {link:troggs}троггов{/link} глубин. Каким бы ни было их начало, они досаждали уже первым поселенцам {link:tirisfal-glades}Тирисфаль{/link}ских лесов и с тех пор не дают покоя рудокопам.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Кобольды любят темные ходы, но боятся настоящей тьмы, и свечи — самое дорогое, что у них есть. Украсть свечу — худшее из преступлений, и вор об этом услышит. Они роют без конца и тащат к себе все, что блестит. Их геоманты владеют грубой магией огня и камня. Большинство дерется, только когда их загонят в угол, но толпой они могут одолеть беспечного рудокопа.]=],
		},
		{
			title = "Наши дни",
			text = [=[Кобольды кишат в шахтах {link:elwynn-forest}Элвиннского леса{/link} и {link:westfall}Западного Края{/link}, где роют золото, которое не задерживается в их руках. Говорят, что ими помыкают {link:riverpaw-gnolls}гноллы Речной Лапы{/link}, а те, в свой черед, ведут дела с {link:defias-brotherhood}Братством Справедливости{/link}. {link:tunnel-rat-kobolds}Кобольды Туннельной Крысы{/link} досаждают {link:dwarves}дворф{/link}ам {link:loch-modan}Лок Модана{/link}, а в {link:kalimdor}Калимдоре{/link} кобольды роют для {link:venture-company}Торговой Компании{/link} в {link:stonetalon-mountains}Когтистых горах{/link}.]=],
		},
	},
})

Translate("ruRU", "gnolls", {
	title = "Гноллы",
	aliases = { "гнолл" },
	sections = {
		{
			title = "Обзор",
			text = [=[Гноллы — существа, похожие на гиен, которые бродят по диким местам {link:eastern-kingdoms}Восточных королевств{/link} и {link:kalimdor}Калимдора{/link}. Они грубы, сварливы и вечно голодны, а силу ценят превыше всего. Они живут стаями и кланами, каждым из которых правит сильнейший, и совершают набеги на фермы и дороги других народов ради еды и добычи.]=],
		},
		{
			title = "Истоки",
			text = [=[Гноллы — старый народ {link:azeroth}Азерот{/link}а, и ни одна летопись не говорит об их начале. Они были среди опасностей, с которыми столкнулись первые поселенцы-люди на севере. {link:kingdom-of-stormwind}Королевство Штормград{/link} помнит более темное время, когда вожак гноллов Красногорья Гарфанг собрал кланы в великое войско и ударил по фермам королевства. Король Баратен Ринн выехал ему навстречу и убил его, и стаи растерзали друг друга в борьбе, которая началась потом.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Гноллы предпочитают, чтобы их работу делали другие. Их вожаки гонят слабых перед собой, и они охотно служат любому более сильному хозяину, который обещает им еду и добычу. Их мистики знают грубое шаманство. У них хватает хитрости, чтобы ставить ловушки и засады, и жестокости, чтобы находить в этом удовольствие.]=],
		},
		{
			title = "Наши дни",
			text = [=[Гноллы тревожат почти все рубежи человеческих земель. {link:riverpaw-gnolls}Гноллы Речной Лапы{/link} совершают набеги на {link:elwynn-forest}Элвиннский лес{/link} и {link:westfall}Западный Край{/link}. Стая Красногорья и {link:shadowhide-gnolls}Темношкуры{/link} рыщут по {link:redridge-mountains}Красногорью{/link}, причем последние в рабстве у чернокнижника {link:morganth}Морганта{/link}. Мохошкуры обитают в {link:wetlands}Болотине{/link}, Гнилошкуры выкапывают мертвецов {link:tirisfal-glades}Тирисфальских лесов{/link} для {link:scourge}Плети{/link}, а другие кланы бродят по холмам {link:hillsbrad-foothills}Хилсбрада{/link} и по лесам {link:feralas}Фераласа{/link}.]=],
		},
	},
})

Translate("ruRU", "riverpaw-gnolls", {
	title = "Гноллы Речной Лапы",
	aliases = { "гноллы Речной Лапы", "Речная Лапа" },
	sections = {
		{
			title = "Обзор",
			text = [=[Речная Лапа — клан {link:gnolls}гнолл{/link}ов, который разоряет южные земли {link:kingdom-of-stormwind}королевства Штормград{/link}. Они бродят вдоль границы {link:elwynn-forest}Элвиннского леса{/link}, по полям {link:westfall}Западного Края{/link} и в сторону {link:redridge-mountains}Красногорья{/link}. Они грабят фермы, подстерегают путников и дерутся с теми немногими солдатами, которых королевство может выделить. Страшнее всех среди них {link:ogres}огр{/link}омный гнолл {link:hogger}Дробитель{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[Гноллы Речной Лапы осмелели с тех пор, как армию королевства отправили в чужие края. Они выходят с Лесной опушки и нападают на фермы на юге {link:elwynn-forest}Элвинн{/link}ского леса, а {link:westbrook-garrison}Гарнизон у Западного ручья{/link} платит награду за каждую лапу, которую приносят его добровольцы. В Западном Крае их лагеря еще больше. Народное ополчение нашло следы того, что Речная Лапа дерется не только за себя: {link:gnolls}гнолл{/link}ы гоняют рабов-{link:kobolds}кобольдов{/link} в шахтах и ведут дела с {link:defias-brotherhood}Братством Справедливости{/link}. Многие в {link:stormwind-city}Штормград{/link}е гадают, кто их вооружает и кто дает им необычную для них хитрость.]=],
		},
	},
})

Translate("ruRU", "murlocs", {
	title = "Мурлоки",
	aliases = { "мурлок" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мурлоки — мелкие существа, похожие на рыб, которые живут по берегам морей, озер и рек {link:azeroth}Азерота{/link}. Они ходят на двух ногах, говорят на булькающем языке, которого не понимает ни один другой народ, и нападают внезапными толпами. У каждого рыбака {link:eastern-kingdoms}Восточных королевств{/link} и {link:kalimdor}Калимдора{/link} найдется рассказ о мурлоках.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не говорит, откуда взялись мурлоки. Они обитают на берегах мира столько, сколько какой-либо народ ведет записи, и, похоже, им нет дела до войн жителей суши.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Мурлоки живут племенами, в деревнях из хижин, построенных у самой воды. Они ловят рыбу и все прочее, что забредет к их берегам. Их оракулы и охотники приливов владеют простой магией воды и бури. В одиночку они редко опасны, но в одиночку они редко и приходят. Когда на одного мурлока нападают, другие появляются с мелководья со страшным криком.]=],
		},
		{
			title = "Наши дни",
			text = [=[Мурлоки осмелели, пока королевства слабеют. Они совершают набеги на берега озер {link:elwynn-forest}Элвиннского леса{/link} и на побережье {link:westfall}Западного Края{/link}. Племя Синежабрых обитает в топях {link:wetlands}Болотины{/link}, а племя Серой Мглы — на берегах {link:darkshore}Темных берегов{/link}. На каждом побережье, от {link:stranglethorn-vale}Тернистой долины{/link} до {link:durotar}Дуротара{/link}, их хижины стоят у кромки воды.]=],
		},
	},
})

Translate("ruRU", "quilboar", {
	title = "Свинобразы",
	aliases = { "свинобраз" },
	sections = {
		{
			title = "Обзор",
			text = [=[Свинобразы — дикий народ людей-вепрей, который обитает на юге {link:the-barrens}Степей{/link} и в землях вокруг. Они покрыты щетиной и шипами и устраивают жилища среди {link:ogres}огр{/link}омных переплетенных терновых лоз. Они враждебны почти всем другим народам и издавна воюют с {link:tauren}тауренами{/link} и {link:orcs}орк{/link}ами.]=],
		},
		{
			title = "Истоки",
			text = [=[Свинобразы считают себя детьми полубога Агамаггана, великого вепря. В {link:war-of-the-ancients}Войну древних{/link} Агамагган сражался против {link:burning-legion}Пылающего Легиона{/link} и был убит. Там, где упала его кровь, из земли выросли громадные терновые лозы. Эти тернии стали землей Иглошкурых, и свинобразы сделали их своим священным домом.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Свинобразы свирепы и ревниво стерегут свои земли. Их племена ведут военные вожди, а их геоманты взывают к земле. Они чтят память полубога Агамаггана и считают тернии Иглошкурых святыней. Некоторые их жрицы обратились к более темным искусствам, а некоторые их воины — к более темным хозяевам.]=],
		},
		{
			title = "Наши дни",
			text = [=[Племя Игл{link:ogres}огр{/link}ивых совершает набеги на окраины {link:durotar}Дуротара{/link} и на север Степей, а племя Дыбогривов тревожит равнины {link:mulgore}Мулгора{/link}. На юге свинобразы живут в огромных терновых лабиринтах: в {link:razorfen-kraul}Лабиринтах Иглошкурых{/link} и в {link:razorfen-downs}Курганах Иглошкурых{/link}. Говорят, что в Курганах культ под названием {link:death-s-head}Мертвая Голова{/link} обратился к {link:scourge}Плети{/link} и что теперь среди них обитает лич.]=],
		},
	},
})

Translate("ruRU", "centaurs", {
	title = "Кентавры",
	aliases = { "кентавр" },
	sections = {
		{
			title = "Обзор",
			text = [=[Кентавры — жестокий и воинственный народ {link:kalimdor}Калимдора{/link}. У них торс человека и тело коня, и они страшные налетчики, которые скачут быстрыми и безжалостными ватагами. Поколениями они были злейшими врагами {link:tauren}тауренов{/link}.]=],
		},
		{
			title = "Истоки",
			text = [=[Говорят, что кентавры происходят от союза, в который вступили Зейтар, сын полубога {link:cenarius}Кенария{/link}, и Терадрас, принцесса стихии земли. Их первые дети были жестоки сверх всякой меры и в приступе ревности убили собственного отца. Терадрас упокоила его тело в пещерах {red:maraudon}Мародона{/red}, где, как говорят, его дух пребывает до сих пор.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Кентавры живут кочевниками и налетчиками. Они считают, что сильный должен брать у слабого все, что захочет. Племена ведут их ханы, а когда других врагов нет, племена воюют между собой. Они искусные наездники и лучники и почти не знают пощады.]=],
		},
		{
			title = "Наши дни",
			text = [=[Племя {link:kolkar-centaurs}Колкар{/link} кочует по {link:the-barrens}Степям{/link}, и его налетчики бьют по тамошним заставам {link:orcs}орк{/link}ов. Племя Галак скачет по {link:thousand-needles}Тысяче Игл{/link}. В {link:desolace}Пустошах{/link} племена Маграм и Гелкис ведут долгую вражду, и оба уверяют, что им благоволит Терадрас. Племя Мародин стережет вход в сам Мародон. Хотя {link:cairne-bloodhoof}Кэрн{/link} изгнал кентавров из {link:mulgore}Мулгора{/link}, {link:tauren}таурен{/link}ов они не забыли.]=],
		},
	},
})

Translate("ruRU", "furbolgs", {
	title = "Фурболги",
	aliases = { "фурболг" },
	sections = {
		{
			title = "Обзор",
			text = [=[Фурболги — народ, похожий на медведей, из северных лесов {link:kalimdor}Калимдора{/link}. Долгое время они были кротким и мирным племенем, друзьями {link:night-elves}ночных эльфов{/link} и друидов. В последние годы на большинство их племен пала болезнь духа, и многие фурболги стали дикими и враждебными.]=],
		},
		{
			title = "Истоки",
			text = [=[Фурболги живут в лесах {link:kalimdor}Калимдор{/link}а с древних времен. Некогда их числили среди союзников народа {link:night-elves}калдореи{/link}. Подробнее об их начале не говорит ни одна летопись.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Фурболги живут племенами, в берлогах и деревнях, укрытых глубоко в лесу. Их шаманы мудры в лесных делах. Большинству было довольно жить тихо и мирно торговать с соседями.]=],
		},
		{
			title = "Наши дни",
			text = [=[Демоническая скверна, оставшаяся в лесах после {link:third-war}Третьей войны{/link}, свела многие племена с ума. Племена Колючего Меха и Гиблой Чащи в {link:ashenvale}Ясеневом лесу{/link}, {link:deadwood-furbolgs}племя Мертвого Леса{/link} в {link:felwood}Оскверненном лесу{/link}, {link:blackwood-furbolgs}племя Чернолесья{/link} на {link:darkshore}Темных берегах{/link}, {link:gnarlpine-furbolgs}племя Кривой Сосны{/link} на {link:teldrassil}Тельдрассиле{/link} и {link:winterfall-furbolgs}племя Зимней Спячки{/link} в {link:winterspring}Зимних Ключах{/link} обратились против своих старых друзей. Одни лишь {link:timbermaw-furbolgs}Древобрюхи{/link} устояли против порчи. Они стерегут проходы Крепости Древобрюхов и не доверяют ни одному чужаку, пока тот не покажет себя на деле.]=],
		},
	},
})

Translate("ruRU", "harpies", {
	title = "Гарпии",
	aliases = { "гарпия" },
	sections = {
		{
			title = "Обзор",
			text = [=[Гарпии — крылатые существа {link:kalimdor}Калимдора{/link} с телами женщин и с крыльями и когтями птиц. Они жестоки, хитры и злобны и охотятся на путников из своих гнезд на высотах.]=],
		},
		{
			title = "Истоки",
			text = [=[О происхождении гарпий не говорит ни одна летопись, известная этому своду.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Гарпии живут стаями, которыми правят матриархи. Они гнездятся на утесах и гребнях и бросаются сверху на все, что слабее их. Они любят краденые блестящие вещи и плоть тех, кого поймают. Их ведьмы повелевают темной магией.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:windfury-harpies}Гарпии Ярости Ветра{/link} гнездятся на грядах {link:mulgore}Мулгора{/link}, к великой досаде {link:tauren}таурен{/link}ов. Гарпии Ведьмина Крыла устроили насесты в {link:the-barrens}Степях{/link}, Кровавой Ярости — в {link:stonetalon-mountains}Когтистых горах{/link}, а Северного Ключа — в {link:feralas}Фераласе{/link}. Дороги {link:kalimdor}Калимдор{/link}а под их гнездами небезопасны.]=],
		},
	},
})

Translate("ruRU", "troggs", {
	title = "Трогги",
	aliases = { "трогг" },
	sections = {
		{
			title = "Обзор",
			text = [=[Трогги — грубые существа с каменной кожей, которые живут глубоко под землей. Они сильны, глупы и бесконечно злобны. Веками они были скрыты в глубинах. Теперь они вышли на поверхность и принесли с собой разорение.]=],
		},
		{
			title = "Истоки",
			text = [=[Записи {link:uldaman}Ульдамана{/link} говорят, что троггов, как и земельников, создали титаны. Они были неудачным творением, и титаны запечатали их в глубоких хранилищах мира. {link:explorers-league}Лига исследователей{/link} считает, что {link:dwarves}дворф{/link}ы потревожили эти хранилища, когда копали в Ульдамане, и что с тех пор трогги расползаются все шире.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Трогги живут племенами, которые ведут сильнейшие из них. Их шаманы владеют грубой магией земли. Им мало до чего есть дело, кроме драки и еды.]=],
		},
		{
			title = "Наши дни",
			text = [=[Трогги поднялись под {link:gnomeregan}Гномреганом{/link} и выгнали {link:gnomes}гном{/link}ов из их города. Они дерутся с {link:dwarves}дворф{/link}ами в {link:dun-morogh}Дун Мороге{/link} и {link:loch-modan}Лок Модане{/link} и кишат в {link:uldaman}Ульдаман{/link}е и в {link:badlands}Бесплодных землях{/link}. Всюду, где дворфы копают глубоко, они боятся найти новых троггов.]=],
		},
	},
})

Translate("ruRU", "ogres", {
	title = "Огры",
	aliases = { "огр" },
	sections = {
		{
			title = "Обзор",
			text = [=[Огры — огромные тупые громилы великой силы. У некоторых две головы, а немногие из них — хитрые чародеи. Большинство пришло в {link:azeroth}Азерот{/link} с {link:orcs}орк{/link}ами из мира Дренор, и теперь многие кланы живут в диких местах обоих материков.]=],
		},
		{
			title = "Истоки",
			text = [=[Огры служили {link:horde}Орде{/link} {link:orcs}орк{/link}ов во {link:second-war}Второй войне{/link}. Чернокнижник {link:gul-dan}Гул'дан{/link} наделил некоторых из них даром чародейства, и этих огров-магов стали бояться по всем {link:eastern-kingdoms}Восточным королевствам{/link}. Величайший из них, Чо'галл, вел клан {link:twilight-s-hammer}Сумеречного Молота{/link}. После поражения Орды кланы огров рассеялись по холмам и горам.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Огры воинственны и жадны. Они уважают только силу и дерутся между собой за главенство. Их вожди правят дубиной, а их маги — страхом.]=],
		},
		{
			title = "Наши дни",
			text = [=[Кланы огров держат холмы {link:redridge-mountains}Красногорья{/link}, {link:stranglethorn-vale}Тернистой долины{/link}, {link:alterac-mountains}Альтерака{/link} и {link:arathi-highlands}Нагорья Арати{/link}. В {link:kalimdor}Калимдоре{/link} огры Гордунни обитают в {link:feralas}Фераласе{/link}, а {link:gordo}Гордо{/link}к правят руинами {red:dire-maul}Забытого Города{/red}. В {link:dustwallow-marsh}Пылевых топях{/link} клан Каменного Молота утратил былую силу, и некоторые его огры живут теперь бок о бок с {link:orcs}орк{/link}ами.]=],
		},
	},
})

Translate("ruRU", "naga", {
	title = "Наги",
	aliases = { "нага" },
	sections = {
		{
			title = "Обзор",
			text = [=[Наги — змееподобные существа морских глубин. Некогда они были ночными эльфами из касты высокорожденных. Теперь у них чешуйчатые хвосты и жестокие лица, и они вернулись из глубин, чтобы тревожить берега мира.]=],
		},
		{
			title = "Истоки",
			text = [=[Когда {link:well-of-eternity}Источник Вечности{/link} был уничтожен в {link:great-sundering}Великом Расколе{/link}, дворец, где правила {link:queen-azshara}королева Азшара{/link}, поглотило море вместе со всем ее двором. Что-то в глубинах спасло их и изменило их. Утонувшие высокорожденные стали нагами. Десять тысяч лет они жили скрытно под волнами. Во времена {link:third-war}Третьей войны{/link} они поднялись вновь и какое-то время служили чародею {link:illidan-stormrage}Иллидану Ярости Бури{/link}.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Наги горды, озлоблены и честолюбивы. Их сирены — могучие чародейки, которые повелевают водами и бурями. Их мирмидоны — грозные воины. Говорят, что в глубинах они до сих пор чтят королеву Азшару.]=],
		},
		{
			title = "Наши дни",
			text = [=[Наги заняли участки побережья в {link:azshara}Азшаре{/link}, на {link:darkshore}Темных берегах{/link}, в {link:ashenvale}Ясеневом лесу{/link} и в {link:desolace}Пустошах{/link}. Они обитают в затопленном храме {link:blackfathom-deeps}Непроглядной Пучины{/link}. Чего они ищут на берегах {link:kalimdor}Калимдор{/link}а, ночные эльфы не знают.]=],
		},
	},
})

Translate("ruRU", "satyrs", {
	title = "Сатиры",
	aliases = { "сатир" },
	sections = {
		{
			title = "Обзор",
			text = [=[Сатиры — лесные демоны, рогатые и козлоногие. Некогда они были ночными эльфами из высокорожденных, которые продались {link:burning-legion}Пылающему Легиону{/link}. Теперь они обитают в оскверненных лесах севера {link:kalimdor}Калимдора{/link} и разносят порчу {link:fel-magic}магии Скверны{/link} всюду, куда приходят.]=],
		},
		{
			title = "Истоки",
			text = [=[В {link:war-of-the-ancients}Войну древних{/link} лорд Ксавий, советник, которому доверяла {link:queen-azshara}королева Азшара{/link}, первым из высокорожденных стал служить демонам. После его поражения хозяин Легиона переделал его в первого сатира. Ксавий, в свой черед, привел к той же участи многих высокорожденных. Сатиры сражались за Легион всю войну, и многие пережили {link:great-sundering}Раскол{/link}.]=],
		},
		{
			title = "Нрав и обычаи",
			text = [=[Сатиры жестоки, лживы и жадны до власти. Они служат демонам, близко Легион или далеко. Их магия — магия Скверны, и они оскверняют землю, на которой живут. Их племена обитают в темных рощах в лесах, которые они разоряют.]=],
		},
		{
			title = "Наши дни",
			text = [=[После Третьей войны сатиры расселились по лесам. Они кишат в {link:felwood}Оскверненном лесу{/link} и в {link:ashenvale}Ясеневом лесу{/link}, где их твердыня — {link:satyrnaar}Сатирнаар{/link}, и таятся в руинах {link:azshara}Азшары{/link} и в глубинах {red:dire-maul}Забытого Города{/red}. {link:sentinels}Часовые{/link} охотятся на них без жалости.]=],
		},
	},
})
